/* file : MakeModelSchedulerMapper.xml, id : updateMakeModelTarget */ UPDATE TB_MODEL SET MODEL_STATUS = 'DOING' WHERE 1 = 1 AND DEL_YN = 'N' AND USE_YN = 'Y'
AND MODEL_SEQ IN
#{item}

mapper.select:
/* file : MakeModelSchedulerMapper.xml, id : getMakeModelDoingList */
SELECT *
  FROM TB_MODEL U
 WHERE U.USE_YN = 'Y' AND U.DEL_YN = 'N'
   AND U.MODEL_STATUS = 'DOING' AND U.PRCS_LEVEL IS NOT NULL
  ORDER BY MDFCN_DT ASC, MODEL_SEQ ASC LIMIT #{limitCnt}

/* file : MakeModelSchedulerMapper.xml, id : setMakeModelOutputColumns */
SELECT *
  FROM TB_MODEL_COLUMN
  WHERE MODEL_SEQ = #{model_seq}
    AND DEL_YN = 'N' AND USE_YN = 'Y'
    AND MODEL_COL_TP = 'OC'

/* file : MakeModelSchedulerMapper.xml, id : setMakeModelFeatureColumns */
SELECT *
  FROM TB_MODEL_COLUMN
  WHERE MODEL_SEQ = #{model_seq}
    AND DEL_YN = 'N' AND USE_YN = 'Y'
    AND MODEL_COL_TP = 'FC'

/* file : MakeModelSchedulerMapper.xml, id : setMakeModelFiles */
SELECT *
  FROM TB_MODEL_FILES
  WHERE MODEL_SEQ = #{model_seq}
    AND DEL_YN = 'N' AND USE_YN = 'Y'
    AND REF_TP = #{ref_tp}

/* file : MakeModelSchedulerMapper.xml, id : getOriginFiles */
SELECT *
  FROM TB_MODEL_FILES
  WHERE MODEL_SEQ = #{model_seq}
    AND DEL_YN = 'N' AND USE_YN = 'Y'
    AND REF_TP = 'ORIGIN'

mapper.update:
/* file : MakeModelSchedulerMapper.xml, id : finishMakeModel */
UPDATE TB_MODEL
     SET MODEL_STATUS = #{model_status}
 WHERE MODEL_SEQ = #{model_seq}

/* file : MakeModelSchedulerMapper.xml, id : updateLearningBgngDt */
UPDATE TB_MODEL
     SET LEARNING_BGNG_DT = CURRENT_TIMESTAMP
 WHERE MODEL_SEQ = #{model_seq}

/* file : MakeModelSchedulerMapper.xml, id : updateLearningDndDt */
UPDATE TB_MODEL
     SET LEARNING_END_DT = CURRENT_TIMESTAMP
 WHERE MODEL_SEQ = #{model_seq}
